import { useEffect, useState } from "react";
import {
  BrowserRouter as Router,
  Routes,
  Route,
  Navigate,
} from "react-router-dom";
import axios from "axios";

import AdminPanel from "./components/AdminPanel";
import AuthPage from "./components/Authpage";
import AdminAnonymousResults from "./components/AdminAnonymousResults";
import UserDashboard from "./components/UserDashboard";
import VotingPage from "./components/VotingPage";

const API_URL = "http://localhost:5000";

function App() {
  // ================= STATE =================
  const [candidates, setCandidates] = useState([]);
  const [darkMode, setDarkMode] = useState(false);
  const [showAnonymous, setShowAnonymous] = useState(false);
  const [electionClosed, setElectionClosed] = useState(false);
  const [editId, setEditId] = useState(null);
  const [message, setMessage] = useState("");

  const [auth, setAuth] = useState({
    token: localStorage.getItem("token") || null,
    role: localStorage.getItem("role") || null,
  });

  const [candidateForm, setCandidateForm] = useState({
    firstName: "",
    lastName: "",
    candidacy: "",
    description: "",
    yearLevel: "",
    block: "",
    image: null,
  });

  const [selectedVotes, setSelectedVotes] = useState({});
  const [submittedVotes, setSubmittedVotes] = useState(null);

  // ================= THEME =================
  const theme = {
    background: darkMode ? "#0f172a" : "#f1f5f9",
    navbar: darkMode ? "#111827" : "#ffffff",
    card: darkMode ? "#1e293b" : "#ffffff",
    text: darkMode ? "#f8fafc" : "#0f172a",
    button: darkMode ? "#4f46e5" : "#6366f1",
  };

  // ================= FETCH CANDIDATES =================
  const fetchCandidates = async () => {
    try {
      const res = await axios.get(`${API_URL}/api/candidates`);
      setCandidates(res.data);
    } catch {
      setMessage("Failed to load candidates.");
    }
  };

  useEffect(() => {
    fetchCandidates();
    const interval = setInterval(fetchCandidates, 3000);
    return () => clearInterval(interval);
  }, []);

  // ================= AUTH =================
  const handleLogout = () => {
    localStorage.clear();
    setAuth({ token: null, role: null });
  };

  if (!auth.token) return <AuthPage setAuth={setAuth} />;

  // ================= SAVE CANDIDATE =================
  const handleSaveCandidate = async () => {
    try {
      const formData = new FormData();
      Object.keys(candidateForm).forEach((key) => {
        if (candidateForm[key]) {
          formData.append(key, candidateForm[key]);
        }
      });

      if (editId) {
        await axios.put(`${API_URL}/api/candidates/${editId}`, formData, {
          headers: { Authorization: `Bearer ${auth.token}` },
        });
        setMessage("Candidate updated.");
      } else {
        await axios.post(`${API_URL}/api/candidates`, formData, {
          headers: { Authorization: `Bearer ${auth.token}` },
        });
        setMessage("Candidate added.");
      }

      setCandidateForm({
        firstName: "",
        lastName: "",
        candidacy: "",
        description: "",
        yearLevel: "",
        block: "",
        image: null,
      });

      setEditId(null);
      fetchCandidates();
    } catch {
      setMessage("Failed to save candidate.");
    }
  };

  const handleDeleteCandidate = async (id) => {
    try {
      await axios.delete(`${API_URL}/api/candidates/${id}`, {
        headers: { Authorization: `Bearer ${auth.token}` },
      });
      fetchCandidates();
    } catch {
      setMessage("Delete failed.");
    }
  };

  // ================= USER VOTE =================
  const handleVoteSubmit = async () => {
    if (Object.keys(selectedVotes).length === 0) {
      alert("Please select at least one candidate.");
      return;
    }

    if (!window.confirm("Are you sure? This cannot be changed."))
      return;

    try {
      await axios.post(
        `${API_URL}/api/votes`,
        { votes: selectedVotes },
        { headers: { Authorization: `Bearer ${auth.token}` } }
      );

      alert("Vote submitted successfully!");
      setSubmittedVotes(selectedVotes);
      setSelectedVotes({});
      fetchCandidates();
    } catch {
      alert("Vote submission failed.");
    }
  };

  const totalVotes = candidates.reduce(
    (sum, c) => sum + (c.votes || 0),
    0
  );

  // ================= UI =================
  return (
    <Router>
      <div
        style={{
          minHeight: "100vh",
          backgroundColor: theme.background,
          color: theme.text,
        }}
      >
        {/* ===== NAVBAR ===== */}
        <div
          style={{
            position: "sticky",
            top: 0,
            zIndex: 1000,
            backgroundColor: theme.navbar,
            padding: "18px 40px",
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
            boxShadow: "0 2px 10px rgba(0,0,0,0.08)",
          }}
        >
          <div>
            <h1 style={{ margin: 0, fontSize: 22 }}>
              SorSU Online Voting
            </h1>
            <small style={{ opacity: 0.6 }}>
              Official Student Election Portal
            </small>
          </div>

          <div style={{ display: "flex", gap: 12 }}>
            <button
              onClick={() => setDarkMode(!darkMode)}
              style={modernButton(theme)}
            >
              {darkMode ? "Light Mode" : "Dark Mode"}
            </button>

            {auth.role === "admin" && (
              <button
                onClick={() => setShowAnonymous(!showAnonymous)}
                style={modernButton(theme)}
              >
                {showAnonymous ? "Hide Chart" : "Anonymous Chart"}
              </button>
            )}

            {auth.role === "admin" && (
              <button
                onClick={() =>
                  setElectionClosed(!electionClosed)
                }
                style={{
                  ...modernButton(theme),
                  backgroundColor: electionClosed
                    ? "#10b981"
                    : "#ef4444",
                }}
              >
                {electionClosed
                  ? "Open Election"
                  : "Close Election"}
              </button>
            )}

            <button
              onClick={handleLogout}
              style={{
                ...modernButton(theme),
                backgroundColor: "#ef4444",
              }}
            >
              Logout
            </button>
          </div>
        </div>

        {/* ===== CENTERED CONTENT ===== */}
        <div
          style={{
            maxWidth: "1200px",
            margin: "40px auto",
            padding: "0 20px",
          }}
        >
          {message && (
            <p style={{ marginBottom: 20 }}>{message}</p>
          )}

          <Routes>
            {auth.role === "admin" && (
              <Route
                path="*"
                element={
                  showAnonymous ? (
                    <AdminAnonymousResults theme={theme} />
                  ) : (
                    <>
                      <h2>Live Vote Monitor</h2>
                      <div
                        style={{
                          backgroundColor: theme.card,
                          padding: 15,
                          borderRadius: 8,
                          marginBottom: 20,
                        }}
                      >
                        <strong>Total Votes:</strong>{" "}
                        {totalVotes}
                      </div>

                      <AdminPanel
                        candidateForm={candidateForm}
                        setCandidateForm={setCandidateForm}
                        onSave={handleSaveCandidate}
                        editId={editId}
                        setEditId={setEditId}
                        onDelete={handleDeleteCandidate}
                        candidates={candidates}
                        theme={theme}
                      />
                    </>
                  )
                }
              />
            )}

            {auth.role === "user" && (
              <>
                <Route
                  path="/dashboard"
                  element={
                    <UserDashboard
                      candidates={candidates}
                      selectedVotes={selectedVotes}
                      setSelectedVotes={setSelectedVotes}
                      handleVoteSubmit={handleVoteSubmit}
                      electionClosed={electionClosed}
                      submittedVotes={submittedVotes}
                    />
                  }
                />
                <Route
                  path="/vote"
                  element={
                    <VotingPage
                      candidates={candidates}
                      selectedVotes={selectedVotes}
                      setSelectedVotes={setSelectedVotes}
                      handleVoteSubmit={handleVoteSubmit}
                      electionClosed={electionClosed}
                    />
                  }
                />
                <Route
                  path="*"
                  element={<Navigate to="/dashboard" />}
                />
              </>
            )}
          </Routes>
        </div>
      </div>
    </Router>
  );
}

// ===== MODERN BUTTON STYLE =====
const modernButton = (theme) => ({
  padding: "8px 14px",
  backgroundColor: theme.button,
  color: "#fff",
  border: "none",
  borderRadius: "8px",
  cursor: "pointer",
  fontWeight: "500",
  fontSize: "14px",
  transition: "0.2s ease",
});

export default App;
